```cpp
#include <iostream>
#include <string>
#include <markdown/markdown.hpp>

std::string markdownToHtml(const std::string& markdownText) {
    // Convert Markdown to HTML
    std::string htmlText = markdown::transform(markdownText);
    return htmlText;
}

int main() {
    std::string markdownText = "# Hello\n\nThis is a sample paragraph.";
    std::string htmlText = markdownToHtml(markdownText);
    std::cout << "Markdown Text: " << markdownText << std::endl;
    std::cout << "HTML Text: " << htmlText << std::endl;
    return 0;
}
```

This function uses the `markdown::transform` function from the Markdown library to convert the markdown text to HTML. The `main` function demonstrates how to use the `markdownToHtml` function by converting a sample markdown string to HTML and printing the results.

Please note that the Markdown library is not included in this example. You will need to install the Markdown library and include it in your project path to use it in your project.

